class ColonialRecordNormalizer:
    def __init__(self):
        # 1. Legal Abbreviation Mapping
        self.abbrev_map = {
            'hn': 'hijo natural',
            'hl': 'hijo legitimo',
            'id': 'indigena',
            'indo': 'indio'
        }

        # 2. Canonical Taxonomies for Facets
        self.taxonomies = {
            "Ethno-Racial Category": {
                "Indígena": ["indigena", "indigino", "indigina", "indijena", "indijina", "indio", "india", "indios"],
                "Español": ["espanol", "espanola"],
                "Mestizo": ["mestiza", "mestizo"]
            },
            "Legitimacy Status": {
                "Legítimo": ["legitimo", "legitima", "legitimos", "hijo legitimo", "hija legitima"],
                "Natural": ["natural", "naturales", "hijo natural", "hija natural"],
                "Espurio": ["espurio", "espuria"]
            },
            "Geographic Location": {
                "Aucara": ["aucara"],
                "Ishua": ["ishua"],
                "Pampamarca": ["pampamarca"],
                "Chacralla": ["chacralla"],
                "Punas": ["punas"]
            }
        }

    def normalize_term(self, term):
        term = term.lower().strip()

        # Resolve abbreviations first
        for abbrev, full in self.abbrev_map.items():
            if term == abbrev:
                return full
        return term

    def classify_term(self, term):
        normalized = self.normalize_term(term)

        # Check for multi-word terms (e.g., "indio aucara") by splitting
        tokens = re.split(r'\s+', normalized)

        results = {
            "Ethno-Racial Category": None,
            "Legitimacy Status": None,
            "Geographic Location": None
        }

        for token in tokens:
            for facet, categories in self.taxonomies.items():
                for canonical, variants in categories.items():
                    # Use RapidFuzz for scribal variation (threshold 85% similarity)
                    # This handles 'indijena' -> 'indigena'
                    match = process.extractOne(token, variants, scorer=fuzz.WRatio)
                    if match and match[1] >= 85:
                        results[facet] = canonical
                        break
        return results

    def parse_clusters(self, text):
        structured_data = {}
        lines = text.strip().split('\n')

        for line in lines:
            if ':' not in line: continue

            cluster_id, terms_str = line.split(':', 1)
            cluster_id = cluster_id.strip()
            terms = [t.strip() for t in terms_str.split(',')]

            # Aggregate facets for the entire cluster
            cluster_facets = {
                "Ethno-Racial Category": set(),
                "Legitimacy Status": set(),
                "Geographic Location": set()
            }

            for term in terms:
                classification = self.classify_term(term)
                for facet, value in classification.items():
                    if value:
                        cluster_facets[facet].add(value)

            # Convert sets to sorted lists for JSON determinism
            structured_data[cluster_id] = {
                "normalized_facets": {k: sorted(list(v)) for k, v in cluster_facets.items()},
                "raw_terms": terms
            }

        return structured_data

