import time
import random

class SegmentTree:
    """
    Implementation of a Segment Tree for Range Sum Queries (RSQ) 
    and Point Updates.
    """
    def __init__(self, data):
        self.n = len(data)
        self.tree = [0] * (4 * self.n)
        self._build(data, 1, 0, self.n - 1)

    def _build(self, data, node, start, end):
        if start == end:
            self.tree[node] = data[start]
        else:
            mid = (start + end) // 2
            self._build(data, 2 * node, start, mid)
            self._build(data, 2 * node + 1, mid + 1, end)
            self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def update(self, idx, val):
        self._update(1, 0, self.n - 1, idx, val)

    def _update(self, node, start, end, idx, val):
        if start == end:
            self.tree[node] = val
        else:
            mid = (start + end) // 2
            if start <= idx <= mid:
                self._update(2 * node, start, mid, idx, val)
            else:
                self._update(2 * node + 1, mid + 1, end, idx, val)
            self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def query(self, l, r):
        return self._query(1, 0, self.n - 1, l, r)

    def _query(self, node, start, end, l, r):
        if r < start or end < l:
            return 0
        if l <= start and end <= r:
            return self.tree[node]
        mid = (start + end) // 2
        p1 = self._query(2 * node, start, mid, l, r)
        p2 = self._query(2 * node + 1, mid + 1, end, l, r)
        return p1 + p2

def naive_range_sum(arr, l, r):
    # Python's slicing and sum() are implemented in C, 
    # but the complexity remains O(N)
    return sum(arr[l:r+1])

def naive_update(arr, idx, val):
    arr[idx] = val

def run_benchmark(N=10000, Q=5000):
    print(f"Benchmarking: N={N}, Q={Q}")
    print("-" * 40)

    # Generate synthetic dataset
    initial_data = [random.randint(0, 100) for _ in range(N)]
    # Pre-generate operations to ensure both methods perform identical work
    ops = []
    for _ in range(Q):
        op_type = random.choice(['update', 'query'])
        if op_type == 'update':
            ops.append(('update', random.randint(0, N-1), random.randint(0, 100)))
        else:
            l = random.randint(0, N-1)
            r = random.randint(l, N-1)
            ops.append(('query', l, r))

    # --- Naive Strategy ---
    naive_arr = list(initial_data)
    start_time = time.time()
    for op in ops:
        if op[0] == 'update':
            naive_update(naive_arr, op[1], op[2])
        else:
            naive_range_sum(naive_arr, op[1], op[2])
    naive_duration = time.time() - start_time
    print(f"Naive Strategy Time:     {naive_duration:.4f} seconds")

    # --- Segment Tree Strategy ---
    st = SegmentTree(initial_data)
    start_time = time.time()
    for op in ops:
        if op[0] == 'update':
            st.update(op[1], op[2])
        else:
            st.query(op[1], op[2])
    st_duration = time.time() - start_time
    print(f"Segment Tree Time:       {st_duration:.4f} seconds")

    print("-" * 40)
    print(f"Speedup Factor: {naive_duration / st_duration:.2f}x")

if __name__ == "__main__":
    run_benchmark()
